mapper.sql:
SELECT p.id, p.name, p.description, p.image, p.region AS product_region, p.vintage AS product_vintage, c.name AS category_name, f.name AS family_name, b.name AS brand_name, (SELECT pp.price FROM product_price pp WHERE pp.product_id = p.id ORDER BY pp.quantity LIMIT 1) AS price, (SELECT pb.promotion_price FROM product_barcode pb WHERE pb.product_id = p.id AND pb.promotion_price IS NOT NULL ORDER BY pb.id LIMIT 1) AS promo_price, COALESCE(( SELECT SUM(pi.quantity) FROM product_inventory pi WHERE pi.product_id = p.id
AND pi.outlet_id = #{outletId}
), 0) AS stock_quantity, p.track_inventory AS track_inventory, p.case_quantity AS case_quantity, wp.wine_type AS stored_wine_type, wp.source AS stored_profile_source, wp.dryness AS stored_dryness, wp.body AS stored_body, wp.fruitiness AS stored_fruitiness, wp.oak AS stored_oak, wp.tannin AS stored_tannin, wp.varietal AS stored_varietal, wp.region AS stored_region, wp.vintage AS stored_vintage, wp.aroma_tags AS stored_aroma_tags, wp.palate_tags AS stored_palate_tags, wp.food_tags AS stored_food_tags, wp.finish_note AS stored_finish_note FROM product p LEFT JOIN category c ON c.id = p.category_id LEFT JOIN family f ON f.id = p.family_id LEFT JOIN brand b ON b.id = p.brand_id LEFT JOIN product_wine_profile wp ON wp.product_id = p.id WHERE p.deleted_at IS NULL AND p.status = 'ACTIVE'
